/**
 * ZENTRA Field — Server ID vs Local ID Identity Mapping
 * apps/field/src/domain/identity/identity-map.ts
 *
 * Disambiguates between:
 * - SERVER ID: Authoritative UUID generated by backend PostgreSQL
 * - LOCAL ID: WatermelonDB internal row identifier
 *
 * Implements deterministic client operation ID generation via monotonic UUIDv7.
 */

import { generateUuidV7 } from '@zentra/shared';
export { isValidUuid, UUID_REGEX } from './uuid-validator';

export interface EntityIdentity {
  entityType: string;
  localId: string;
  serverId?: string | null;
}

export class IdentityMap {
  private readonly localToServer = new Map<string, string>();
  private readonly serverToLocal = new Map<string, string>();

  /**
   * Register a bidirectional mapping between a local entity ID and a server ID
   */
  register(entityType: string, localId: string, serverId: string): void {
    const localKey = `${entityType}:${localId}`;
    const serverKey = `${entityType}:${serverId}`;
    this.localToServer.set(localKey, serverId);
    this.serverToLocal.set(serverKey, localId);
  }

  getServerId(entityType: string, localId: string): string | null {
    return this.localToServer.get(`${entityType}:${localId}`) || null;
  }

  getLocalId(entityType: string, serverId: string): string | null {
    return this.serverToLocal.get(`${entityType}:${serverId}`) || null;
  }

  clear(): void {
    this.localToServer.clear();
    this.serverToLocal.clear();
  }

  /**
   * Generates monotonic client operation ID using UUIDv7
   */
  static generateOperationId(): string {
    return generateUuidV7();
  }
}
